import Image from "next/image";

interface FeatureCard {
  title: string
  description: string
  imageUrl: string
}

const features: FeatureCard[] = [
  {
    title: "Training & Fitness Resources",
    description: "Explore a variety of training programs designed to enhance athletic performance and overall fitness.",
    imageUrl: "https://hebbkx1anhila5yf.public.blob.vercel-storage.com/bsf2(2).png-xaZDb8jCLrGyM5eHeMIG62uodTx92f.jpeg",
  },
  {
    title: "Equipment & Sponsorship Assistance",
    description: "Get help with acquiring equipment and securing sponsorships for your sports activities.",
    imageUrl: "https://hebbkx1anhila5yf.public.blob.vercel-storage.com/bsf2(2).png-xaZDb8jCLrGyM5eHeMIG62uodTx92f.jpeg",
  },
  {
    title: "Health & Wellness Support",
    description: "Find resources and support for maintaining optimal health and wellness in athletics.",
    imageUrl: "https://hebbkx1anhila5yf.public.blob.vercel-storage.com/bsf2(2).png-xaZDb8jCLrGyM5eHeMIG62uodTx92f.jpeg",
  },
  {
    title: "Scholarship Opportunities",
    description: "Access information about athletic scholarships and sports career opportunities.",
    imageUrl: "https://hebbkx1anhila5yf.public.blob.vercel-storage.com/bsf2(2).png-xaZDb8jCLrGyM5eHeMIG62uodTx92f.jpeg",
  },
]

export default function FeatureGrid() {
  return (
    <div className="container mx-auto px-4 py-12">
      <div className="grid gap-6 md:grid-cols-2">
        {features.map((feature) => (
          <div
            key={feature.title}
            className="group overflow-hidden rounded-lg border bg-card text-card-foreground shadow transition-all hover:shadow-lg"
          >
            <div className="relative h-48 overflow-hidden">
              <Image
                // src={feature.imageUrl || "/placeholder.svg"}
                // alt={feature.title}
                // fill
                className="object-cover transition-transform duration-300 group-hover:scale-105"
                sizes="(max-width: 768px) 100vw, (max-width: 1200px) 50vw"
              />
            </div>
            <div className="p-6">
              <h3 className="mb-2 text-xl font-semibold">{feature.title}</h3>
              <p className="text-sm text-muted-foreground">{feature.description}</p>
            </div>
          </div>
        ))}
      </div>
    </div>
  )
}

